window.ScripturaLexicons.BDAG_PART_0039 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apantao-bdag\" data-source=\"BDAG\" data-search=\"ἀπαντάω apantao encontrar ir encontro Marcos Lucas Atos Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαντάω</td><td>Verbo</td><td>encontrar; ir ao encontro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apantesis-bdag\" data-source=\"BDAG\" data-search=\"ἀπάντησις apantesis encontro ir ao encontro Mateus Atos Tessalonicenses BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάντησις</td><td>Substantivo feminino</td><td>encontro; ir ao encontro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hapax-bdag\" data-source=\"BDAG\" data-search=\"ἅπαξ hapax uma vez novamente mais de uma vez de uma vez por todas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅπαξ</td><td>Advérbio</td><td>uma vez; de uma vez por todas</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hapaxaplos-bdag\" data-source=\"BDAG\" data-search=\"ἁπαξαπλῶς hapaxaplos em geral Atos Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπαξαπλῶς</td><td>Advérbio</td><td>em geral</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparabatos-bdag\" data-source=\"BDAG\" data-search=\"ἀπαράβατος aparabatos permanente imutável sem sucessor Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαράβατος</td><td>Adjetivo</td><td>permanente; imutável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparaskeuastos-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρασκεύαστος aparaskeuastos despreparado não pronto Coríntios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρασκεύαστος</td><td>Adjetivo</td><td>não preparado; despreparado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparthe-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρθῇ, -ῶ aparthe remissão apairo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρθῇ, -ῶ</td><td>Remissão</td><td>veja ἀπαίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparneomai-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρνέομαι aparneomai negar renegar reconhecer negar-se Pedro Mateus Marcos Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρνέομαι</td><td>Verbo</td><td>negar; renegar; negar-se a si mesmo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparti-oxytone-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρτί aparti exatamente certamente expressamente Apocalipse Mateus João BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρτί</td><td>Advérbio</td><td>exatamente; certamente; expressamente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparti-paroxytone-bdag\" data-source=\"BDAG\" data-search=\"ἀπάρτι aparti agora mesmo desde agora João Apocalipse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάρτι</td><td>Advérbio</td><td>agora mesmo; desde agora</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apartizo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρτίζω apartizo terminar completar aperfeiçoar Inácio Policarpo Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρτίζω</td><td>Verbo</td><td>terminar; completar; aperfeiçoar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apartisma-bdag\" data-source=\"BDAG\" data-search=\"ἀπάρτισμα apartisma completação consumação imortalidade Inácio Filadélfia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάρτισμα</td><td>Substantivo neutro</td><td>completação; consumação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apartismos-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρτισμός apartismos completação torre Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρτισμός</td><td>Substantivo masculino</td><td>completação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aparche-bdag\" data-source=\"BDAG\" data-search=\"ἀπαρχή aparche primícias primeira porção primeiros convertidos Espírito certificado nascimento Romanos Coríntios Tiago Apocalipse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαρχή</td><td>Substantivo feminino</td><td>primícias; primeira porção; certificado de nascimento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hapas-bdag\" data-source=\"BDAG\" data-search=\"ἅπας hapas todo inteiro todos juntos Mateus Lucas Atos Gálatas Tiago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅπας</td><td>Adjetivo</td><td>todo; inteiro; todos juntos</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apaspazomai-bdag\" data-source=\"BDAG\" data-search=\"ἀπασπάζομαι apaspazomai despedir dizer adeus Atos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπασπάζομαι</td><td>Verbo</td><td>despedir-se; dizer adeus</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apatao-bdag\" data-source=\"BDAG\" data-search=\"ἀπατάω apatao enganar desencaminhar seduzir deleitar-se Efésios Timóteo Tiago Hermas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπατάω</td><td>Verbo</td><td>enganar; desencaminhar; deleitar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apate-bdag\" data-source=\"BDAG\" data-search=\"ἀπάτη apate engano fraude caráter enganoso prazer pecado Mateus Marcos Hebreus Colossenses Tessalonicenses Efésios Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάτη</td><td>Substantivo feminino</td><td>engano; caráter enganoso; prazer pecaminoso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apatelos-bdag\" data-source=\"BDAG\" data-search=\"ἀπατηλός apatelos enganoso falaz especioso Atos Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπατηλός</td><td>Adjetivo</td><td>enganoso; falaz</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apatrikos-bdag\" data-source=\"BDAG\" data-search=\"ἀπατρικός apatrikos sem pai restauração errônea Oxirrinco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπατρικός</td><td>Adjetivo</td><td>sem pai; restauração errônea</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apator-bdag\" data-source=\"BDAG\" data-search=\"ἀπάτωρ apator sem pai Melquisedeque Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάτωρ</td><td>Adjetivo</td><td>sem pai</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apaugasma-bdag\" data-source=\"BDAG\" data-search=\"ἀπαύγασμα apaugasma resplendor brilho irradiado reflexo Hebreus Cristo glória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαύγασμα</td><td>Substantivo neutro</td><td>resplendor; brilho irradiado; reflexo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apaphrizo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαφρίζω apaphrizo espuma lançar fora Judas variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαφρίζω</td><td>Verbo</td><td>lançar fora como espuma</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apachthenai-bdag\" data-source=\"BDAG\" data-search=\"ἀπαχθῆναι apachthenai remissão apago BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαχθῆναι</td><td>Remissão</td><td>veja ἀπάγω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apebalon-bdag\" data-source=\"BDAG\" data-search=\"ἀπέβαλον apebalon remissão apoballo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέβαλον</td><td>Remissão</td><td>veja ἀποβάλλω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apeben-bdag\" data-source=\"BDAG\" data-search=\"ἀπέβην apeben remissão apobaino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέβην</td><td>Remissão</td><td>veja ἀποβαίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apedeixa-bdag\" data-source=\"BDAG\" data-search=\"ἀπέδειξα apedeixa remissão apodeiknymi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέδειξα</td><td>Remissão</td><td>veja ἀποδείκνυμι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apedeto-bdag\" data-source=\"BDAG\" data-search=\"ἀπέδετο apedeto apedoto forma tardia apodidomi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέδετο</td><td>Forma tardia / remissão</td><td>forma grega tardia de ἀπέδοτο; veja ἀποδίδωμι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apedidoun-bdag\" data-source=\"BDAG\" data-search=\"ἀπεδίδουν apedidoun remissão apodidomi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπεδίδουν</td><td>Remissão</td><td>veja ἀποδίδωμι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apethanon-bdag\" data-source=\"BDAG\" data-search=\"ἀπέθανον apethanon remissão apothnesko BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέθανον</td><td>Remissão</td><td>veja ἀποθνῄσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apethemen-bdag\" data-source=\"BDAG\" data-search=\"ἀπεθέμην apethemen remissão apotithemi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπεθέμην</td><td>Remissão</td><td>veja ἀποτίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apeidon-bdag\" data-source=\"BDAG\" data-search=\"ἀπεῖδον apeidon remissão aphorao BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπεῖδον</td><td>Remissão</td><td>veja ἀφοράω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apeitheia-bdag\" data-source=\"BDAG\" data-search=\"ἀπείθεια apeitheia desobediência incredulidade Deus evangelho Efésios Colossenses Romanos Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπείθεια</td><td>Substantivo feminino</td><td>desobediência; por vezes com conotação de incredulidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apeitheo-bdag\" data-source=\"BDAG\" data-search=\"ἀπειθέω apeitheo desobedecer desobediente Deus ordenanças revelação Romanos João Pedro Hebreus Atos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπειθέω</td><td>Verbo</td><td>desobedecer; ser desobediente</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-apantao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαντάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apantáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπαντήσω</span>, Polieno 2.1.17, em lugar do médio mais antigo e costumeiro; 1º aoristo <span class=\"greek\">ἀπήντησα</span>, com <span class=\"greek\">ἠπήντησα</span> em GJs 19.3; 24.1; perfeito <span class=\"greek\">ἀπήντηκα</span>, Gn 33.8; futuro médio <span class=\"greek\">ἀπαντήσομαι</span>, LXX; aoristo passivo, 3ª singular, <span class=\"greek\">ἀπηντήθη</span>, En 102.5. De <span class=\"greek\">ἀντάω</span>, <strong>“encontrar face a face”</strong>; Eurípides, Heródoto e posteriores. Em Atanásio 4.1; 31.2: <strong>“responder, contrapor”, “responder a acusações”</strong>; veja Anz 351.</p>\n<p class=\"entry-text\"><strong>Encontrar, ir ao encontro de</strong>, com dativo <span class=\"greek\">τινί</span>, alguém; Apiano, <em>Liby.</em> 109 §515, <em>Bell. Civ.</em> 4.36 §152; 1Rs 25.20; Josefo, <em>Ant.</em> 1.179; 6.189. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.16</a> v.l.; GJs 19.3; 24.1, em ambos <span class=\"greek\">ὑπ-</span> em Tdf.</p>\n<p class=\"entry-text\">Sem objeto — Hipérides, Fgm. 205 —: <span class=\"greek\">ἀπήντησαν δέκα λεπροὶ ἄνδρες</span>, <strong>dez homens leprosos vieram ao encontro dele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.12</a>; v.l. <span class=\"greek\">ὑπήντησαν</span>. Em geral, nos manuscritos, <span class=\"greek\">ὑπαντάω</span> alterna com <span class=\"greek\">ἀπαντάω</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.16</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">οὐδέν σοι ἀπήντησεν;</span>, <strong>nada veio ao teu encontro?</strong>, Hv 4.2.3. Pelo contexto, significa <strong>vir ao encontro, aproximar-se</strong>, não <strong>acontecer</strong>; <span class=\"greek\">ἀπαντάω</span> tem este último significado em Políbio 4.38.10; Diodoro Sículo 15.58.4; Gn 49.1; Jr 13.22; Sir 31.22; 33.1; En 98.9; 102.5. — B. 1366. DELG s.v. <span class=\"greek\">ἄντα</span> 1. M-M.</p>\n</section></article><article id=\"entry-apantesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάντησις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apántēsis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπαντάω</span>; Sófocles e posteriores; Políbio 5.26.8; Diodoro Sículo 18.59.3 e outros; inscrições, papiros, LXX; TestJob 9.7; EpArist 91; Josefo, <em>Ant.</em> 7.276; Fílon, <em>Quod Deus</em> 10, 166; veja Nägeli 30; Mlt. 14, n. 4; 242; empréstimo no rabínico. <strong>Encontro</strong>, somente na fórmula <span class=\"greek\">εἰς ἀπάντησιν</span>, <strong>para ir ao encontro</strong>; na LXX, frequentemente em contextos tanto amistosos quanto hostis.</p>\n<p class=\"entry-text\">Absolutamente — PTebt 43 I, 7 [118 a.C.], <span class=\"greek\">παρεγενήθημεν εἰς ἀ.</span>; 1Rs 13.15 —: <span class=\"greek\">ἐξέρχεσθαι εἰς ἀ. [αὐτοῦ]</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.6</a>; muitos manuscritos leem de vários modos um pronome no genitivo ou dativo, e alguns o omitem; veja também as variantes de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.13</a>.</p>\n<p class=\"entry-text\">Com dativo — 1Rs 4.1; 13.10; 1Cr 14.8; Josefo, <em>Ant.</em> 13.101 —: <span class=\"greek\">ἔρχεσθαι εἰς ἀ. τινι</span>, Jdth 5.4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.15</a>. Com genitivo — Pel.-Leg. p. 19; 1Rs 30.21; 2Rs 19.26 —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.32</a> D. <span class=\"greek\">ἁρπάζεσθαι εἰς ἀ. τοῦ κυρίου εἰς ἀέρα</span>, <strong>ser arrebatado para encontrar o Senhor nos ares</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4.17</a>; veja EPeterson, <em>D. Einholung des Kyrios</em>: ZST 7, 1930, 682–702; compare Diodoro Sículo 34+35, Fgm. 33, 2, sobre a introdução da Grande Mãe dos deuses pelos romanos. — DELG s.v. <span class=\"greek\">ἄντα</span> 1. M-M. TW.</p>\n</section></article><article id=\"entry-hapax-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅπαξ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hápax⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Desde Homero; Taciano 6.1, possivelmente eco de Hb 9.26. <strong>“Uma vez”.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Como termo numérico, <strong>relativo a uma ocorrência única, uma vez</strong>. <span class=\"greek\">ἅ. ἐλιθάσθην</span>, <strong>uma vez fui apedrejado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.25</a>. <span class=\"greek\">ἅ. πεφανέρωται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.26</a>. <span class=\"greek\">ἅ. ἀποθανεῖν</span>, v. 27; compare <em>Proverbia Aesopi</em> 141 P.: <span class=\"greek\">‹πλέον ἢ› ἅπαξ οὐδεὶς ἄνθρωπος θνῄσκει</span>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.18</a>. <span class=\"greek\">ἅ. προσενεχθείς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.28</a>.</p>\n<p class=\"entry-text\">Seguido de genitivo: <span class=\"greek\">ἅ. τοῦ ἐνιαυτοῦ</span>, <strong>uma vez por ano</strong>, Heródoto 2.59; Êx 30.10; Lv 16.34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.7</a>. <span class=\"greek\">ἔτι ἅ.</span> — 2Mc 3.37; Jz 16.18, 28; TestAbr A 85, 15 [Stone p. 18] e outros —, <strong>mais uma vez = pela última vez</strong>, Ésquilo, <em>Ag.</em> 1322; Jz 6.39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.26s.</a>, Ag 2.6.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἅ. καὶ δίς</span> — Dionísio de Halicarnasso 8.56.1, <span class=\"greek\">οὐχ ἅ. ἀλλὰ καὶ δίς</span>; Aélio Aristides 36.91 K. = 48 p. 474 D., <span class=\"greek\">ἅ. ἢ δίς</span>; Ana Comnena, <em>Alexias</em> 3.3, ed. Reiff. I 102, 17, <span class=\"greek\">καὶ ἅ. καὶ δίς</span>; 1Rs 17.39; 2Esd 23.20; 1Mc 3.30 —, <strong>repetidamente, mais de uma vez</strong>; LMorris, <em>NovT</em> 1, ’56, 205–8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.18</a>; 1Cl 53.3, Dt 9.13.</p>\n<p class=\"entry-text\">Com enfraquecimento da ideia numérica: <span class=\"greek\">ἐπεὶ ἅ.</span> — Tucídides 7.44.7; Xenofonte, <em>An.</em> 1.9.10; Menandro, PDidot 36 S. p. 329; <em>Dyscolos</em> 392; Chion, <em>Ep.</em> 14.1; POxy 1102, 8, <span class=\"greek\">ἐπεὶ ἄ. προσῆλθε τῇ κληρονομίᾳ</span> —, <strong>já que, desta vez</strong>, Hv 3.3.4; m 4.4.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a uma ocorrência única e decisivamente singular, de uma vez por todas.</strong> Hipócrates, <em>Ep.</em> 27, 41; Eliano, <em>VH</em> 2.30; Filóstrato, <em>Ep.</em> 7.2; PLips 34, 20; 35, 19; Sl 88.36; PsSol 12.6; TestAbr 20 p. 103, 1 [Stone p. 54]; Fílon, <em>Ebr.</em> 198; Josefo, <em>Bell.</em> 2.158, <em>Ant.</em> 4.140; Justino, <em>A I</em> 61.5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">5</a>. Também simplesmente <strong>uma vez</strong>, Alciphron 1.8.4; 1.10.2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6.4</a>. — DELG s.v. <span class=\"greek\">πάξ</span> e <span class=\"greek\">πήγνυμι</span>. EDNT. M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-hapaxaplos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπαξαπλῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hapaxaplō̂s⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma intensiva de <span class=\"greek\">ἁπλῶς</span>; desde o século II d.C.; também TestJob 25.9; 29.3; Taciano 21.3; 32.1. <strong>Em geral.</strong> <span class=\"greek\">ἁπαξα[πλῶς]</span>, ao final de uma recitação dos feitos de Jesus, AcPl BMM verso 12. — DELG s.v. <span class=\"greek\">ἁπλόος</span>.</p>\n</section></article><article id=\"entry-aparabatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαράβατος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aparábatos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">παραβαίνω</span>; pertence ao grego posterior, Phryn. 313 Lob.; não ocorre na LXX. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.24</a>, costuma ser interpretado como <strong>“sem sucessor”</strong>. <strong>Mas esse significado não se encontra em nenhum outro lugar.</strong> Antes, <span class=\"greek\">ἀπαράβατος</span> tem o sentido de <strong>permanente, imutável</strong>.</p>\n<p class=\"entry-text\">Compare Stoic. II 266, 1; 293, 31, Crisipo; Plutarco, <em>Mor.</em> 410f; 745d; Epicteto 2.15.1, <em>Ench.</em> 51.2; Herm. Wr. Fgm. XXIII, 48 [494, 26 Sc.], Fgm. XXIV, 1; Fílon, <em>Aet. M.</em> 112; Josefo, <em>Ant.</em> 18.266, <em>C. Ap.</em> 2.293; Justino, <em>A I</em> 43.7. Como termo técnico jurídico durante longo período em papiros: PRyl 65, 18 [século I a.C.]; PLond III, 1015, 12 p. 257 [século VI d.C.], <span class=\"greek\">ἄτρωτα καὶ ἀσάλευτα καὶ ἀπαράβατα</span>; Mitt-Wilck. II/2, 372 V, 19; PEllingworth, <em>JSNT</em> 23, ’85, 125s. — M-M. TW. Spicq. — DELG s.v. <span class=\"greek\">βαίνω</span>.</p>\n</section></article><article id=\"entry-aparaskeuastos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρασκεύαστος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aparaskeúastos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">παρασκευάζω</span>; Xenofonte e outros; Josefo, <em>Ant.</em> 4.293; veja Nägeli 16. <strong>Não pronto, despreparado</strong>; propriamente, termo técnico militar. <span class=\"greek\">εὑρεῖν τινα ἀ.</span>, <strong>encontrar alguém sem estar preparado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9.4</a>. — DELG s.v. <span class=\"greek\">σκεῦος</span>.</p>\n</section></article><article id=\"entry-aparthe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρθῇ, -ῶ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aparthē̂⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπαίρω</span>.</p>\n</section></article><article id=\"entry-aparneomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρνέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aparnéomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπαρνήσομαι</span>; 1º aoristo <span class=\"greek\">ἀπηρνησάμην</span>. Passivo: 1º futuro <span class=\"greek\">ἀπαρνηθήσομαι</span>; perfeito <span class=\"greek\">ἀπήρνημαι</span>, ISm 5.2; W-S. §13, 9; B-D-F §78; 311. Variante ativa do aoristo <span class=\"greek\">ἀπαρνῆσαι</span>, Hs 1.5. Sófocles, Heródoto e outros; Is 31.7; JosAs 12.11 cód. A em lugar de <span class=\"greek\">ἠρνήσαντο</span>; Melito, <em>P.</em> 26, 181; 73, 537. <strong>“Negar”.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Recusar-se a reconhecer ou admitir, negar</strong>, <span class=\"greek\">τινά</span>, alguém; Is 31.7. De Cristo, na negação de Pedro: MGoguel, “Did Peter Deny his Lord?”, <em>HTR</em> 25, ’32, 1–27; ELinnemann, “Die Verleugnung des Petrus”, <em>ZTK</em> 63, ’66, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.34s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">75</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.30s.</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.72\" target=\"_blank\" rel=\"noopener noreferrer\">72</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.61</a>.</p>\n<p class=\"entry-text\">Em forma plena: <span class=\"greek\">ἕως τρίς με ἀπαρνήσῃ εἰδέναι</span>, <strong>até que três vezes tenhas negado que me conheces</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.34</a>; sobre a v.l. <span class=\"greek\">μὴ εἰδέναι</span>, compare Sófocles, <em>Ant.</em> 442, <span class=\"greek\">καταρνῇ μὴ δεδρακέναι τάδε</span>. <span class=\"greek\">τὸν κύριον</span>, Hv 3.6.5; compare 8.8.2; ISm 5.2; compare Luciano, <em>M. Peregr.</em> 13 p. 337, <span class=\"greek\">θεούς</span>.</p>\n<p class=\"entry-text\">Com acusativo de coisa: Diodoro Sículo 20.63.4, <span class=\"greek\">ἀ. τὴν ἐπιστήμην</span>, <strong>negar, recusar-se a reconhecer seu antigo ofício</strong>, o de oleiro, em oposição a <span class=\"greek\">καυχάομαι</span>, orgulhar-se dele; SibOr 4.27s., <span class=\"greek\">νηοὺς κ. βωμούς</span>; <span class=\"greek\">τ. νόμον</span>, Hs 1.5. No passivo — Sófocles, <em>Philoct.</em> 527; Platão, <em>7th Letter</em> 338e; Herodas 4.74 —: <span class=\"greek\">ἀπαρνηθήσεται ἐνώπιον τῶν ἀγγέλων</span>, <strong>a pessoa será negada</strong>, isto é, <strong>não reconhecida, diante dos anjos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.9</a>; Ps.-Calístenes 2.8.10 usa <span class=\"greek\">ἀπαρνέομαι</span> no sentido de <strong>rejeitar, não querer saber de</strong>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Agir de maneira inteiramente abnegada, negar-se a si mesmo.</strong> Em contraste com Melito, <em>P.</em> 26, 181, onde significa <strong>evitar ser morto</strong>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.23</a> v.l. AFridrichsen, “S. selbst verleugnen”: <em>ConNeot</em> 2, ’36, 1–8; 6, ’42, 94–96; <em>SEÅ</em> 5, ’40, 158–62; JLebreton, “La doctrine du renoncement dans le NT”, <em>NouvRT</em> 65, ’38, 385–412. — DELG s.v. <span class=\"greek\">ἀρνέομαι</span>. M-M. TW.</p>\n</section></article><article id=\"entry-aparti-oxytone-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρτί</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apartí⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Heródoto, Hipócrates e outros; Teleclides [século V a.C.]; Schwyzer I 632s. <strong>Exatamente, certamente, expressamente.</strong> <span class=\"greek\">ἀπαρτί = ἀπηρτισμένως, τελείως, ἀκριβῶς</span>, Phryn. 20s. Lob.; veja Suda s.v. e Bekker, <em>Anecd. Gr.</em> 418, 15; esse significado também é provável em Aristófanes, <em>Pl.</em> 388.</p>\n<p class=\"entry-text\">Considerado por alguns a leitura correta em lugar de <span class=\"greek\">ἀπ’ ἄρτι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.13</a> — assim N.²⁴, ²⁵; <span class=\"greek\">ἀπάρτι</span> Tdf. —, se <span class=\"greek\">ναί</span> for rejeitado como glosa; também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.29</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.64\" target=\"_blank\" rel=\"noopener noreferrer\">64</a> — B-D-F §12; ADebrunner, seguindo AFridrichsen, com inclusão de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.19</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">1.51(52)</a>, <em>ConNeot</em> 11, ’47, 45–49. Em todas as passagens citadas acima, exceto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.51</a>, onde ocorre como v.l., N. lê <span class=\"greek\">ἀπ’ ἄρτι</span>; veja <span class=\"greek\">ἄρτι</span>. — Compare DELG s.v. <span class=\"greek\">ἄρτι</span>. M-M.</p>\n</section></article><article id=\"entry-aparti-paroxytone-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάρτι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apárti⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Agora mesmo, mesmo agora</strong>; uso não ático. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">14.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13.13</a>, todos em Tdf. Veja <span class=\"greek\">ἀπ’ ἄρτι</span> em <span class=\"greek\">ἄρτι</span> 3.</p>\n</section></article><article id=\"entry-apartizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρτίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apartízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀπήρτισα</span>; perfeito passivo <span class=\"greek\">ἀπήρτισμαι</span>, particípio <span class=\"greek\">ἀπηρτισμένος</span>. Ésquilo, <em>Septem</em> 374, embora a leitura seja discutida como expressão tardia — Moeris 75s. [82]; Phryn. 447 Lob. —; Hipócrates e outros; papiros; 3Rs 9.25 A; TestLevi 9.11; Justino; Melito; <span class=\"greek\">πράγματα ἀπηρτισμένα</span>, Teófilo de Antioquia 3.17 [p. 238, 14].</p>\n<p class=\"entry-text\"><strong>Fazer ou realizar algo de maneira precisa ou conclusiva, terminar, completar.</strong> Veja <span class=\"greek\">ἀρτίζω</span>, <strong>“preparar”</strong>; Políbio 31.12.10; 31.13.1; Diodoro Sículo 1.11.6 e outros; POxy 908, 23; 936, 22; PLips 105, 11; veja também Preis.; 3Rs 9.25 A; Josefo, <em>Ant.</em> 3.146; 8.130.</p>\n<p class=\"entry-text\">Com objeto coisa, <span class=\"greek\">τι</span>: <span class=\"greek\">ἔργον τελείως ἀ.</span>, <strong>completar perfeitamente uma tarefa</strong>, IEph 1.1; Melito, <em>P.</em> 38, 265; compare <span class=\"greek\">πρᾶξιν</span>, Justino, <em>D.</em> 134.3. <span class=\"greek\">τὸν ἴδιον κλῆρον</span>, <strong>cumprir seu próprio destino</strong>, MPol 6.2. <span class=\"greek\">ὅταν αὐτὸ ἀπαρτίσητε</span>, <strong>quando o completardes</strong>, IPol 7.3. De Deus: <span class=\"greek\">ὁ ἀπαρτίσας αὐτά</span>, <strong>aquele que os aperfeiçoou</strong>, Hs 5.5.2.</p>\n<p class=\"entry-text\">Também com pessoa, <span class=\"greek\">τινά</span>: POxy 724, 11 [século II d.C.], <span class=\"greek\">ἐὰν αὐτὸν ἀπαρτίσῃς</span>; <strong>tornar alguém completo</strong>, <span class=\"greek\">με ἀπαρτίσει</span>, IPhld 5.1. Passivo: <span class=\"greek\">παρὰ θεῷ ἀπηρτισμένος</span>, IEph 19.3; <span class=\"greek\">ἀπήρτισμαι ἐν Ἰ. Χριστῷ</span>, 3.1. Compare <span class=\"greek\">ἀποτελέω</span>. — DELG s.v. <span class=\"greek\">ἀραρίσκω</span>, <span class=\"greek\">ἄρτι</span>. M-M. s.v. <span class=\"greek\">ἀραρτισμός</span>.</p>\n</section></article><article id=\"entry-apartisma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάρτισμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apártisma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπαρτίζω</span>; 3Rs 7.9 Símaco. <strong>Completação, consumação.</strong> <span class=\"greek\">ἀ. ἀφθαρσίας</span>, <strong>consumação da imortalidade</strong>, IPhld 9.2. Compare DELG s.v. <span class=\"greek\">ἀραρίσκω</span>.</p>\n</section></article><article id=\"entry-apartismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρτισμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apartismós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπάρτισμα</span>; Crisipo, Stoic. II 164; Dionísio de Halicarnasso, <em>De Comp. Verb.</em> 24; Apolônio Díscolo, <em>De Adv.</em> p. 532, 8; papiros em Mitt-Wilck. II/2, 88 IV, 26; PGiss 67, 8ss.; Sb 7173, 30, todos do século II d.C. <strong>Completação.</strong> <span class=\"greek\">ἀ.</span>, subentendido <span class=\"greek\">πύργου</span>, <strong>completação da torre</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.28</a>. — M-M.</p>\n</section></article><article id=\"entry-aparche-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαρχή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aparchḗ⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Compare <span class=\"greek\">ἀπάρχομαι</span>, <strong>“fazer um começo”</strong> no sacrifício; originalmente, dos cabelos cortados da fronte e lançados ao fogo, <em>Il.</em> 19.254; <em>Od.</em> 14.422 e outros; daí <span class=\"greek\">ἀπαρχή</span> = <strong>“começo de um sacrifício”</strong>, Eurípides, <em>Or.</em> 96. Tais sacrifícios começariam com <strong>primeiros produtos/primícias</strong>, frequentemente também distinguidos pela qualidade. Sófocles, Heródoto e outros; inscrições, papiros, LXX; PsSol 15.3; Test12Patr; Fílon; Josefo; Celso 8.33.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Termo técnico cultual: <strong>primícias, primeira porção de qualquer espécie</strong>, inclusive animais domésticos e selvagens — para estes, Arriano, <em>Cyneg.</em> 33.1 —, sagradas à divindade e consagradas antes que o restante pudesse ser destinado ao uso secular. Compare Teopompo [século IV a.C.], 115 Fgm. 344 Jac. p. 608, 5; Cornuto 28 p. 55, 9; Aélio Aristides 45 p. 136 D.; Teofilacto Simocata, <em>Ep.</em> 29, <span class=\"greek\">Πανὶ τοῦ ποιμνίου τὰς ἀπαρχάς</span>; OGI 179, 12 [século I a.C.]; PSI 690, 14; Porfírio, <em>Abst.</em> 2.61, <span class=\"greek\">θεοῖς ἀρίστη μὲν ἀπαρχὴ νοῦς καθαρός</span>; SEG XLII, 17, literalmente.</p>\n<p class=\"entry-text\"><strong>a.</strong> Literalmente: <span class=\"greek\">εἰ ἡ ἀ. ἁγία, καὶ τὸ φύραμα</span>, <strong>se as primícias</strong>, da massa, <strong>são santas, também o é toda a massa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.16</a>; sobre as primícias da massa de pão, Nm 15.18–21; compare <em>The Mishnah</em>, trad. HDanby, ’58 [’33], 83–88, Hallah. Em forma plena: <span class=\"greek\">ἀ. γεννημάτων ληνοῦ καὶ ἅλωνος, βοῶν τε καὶ προβάτων</span>, <strong>as primícias da produção do lagar e da eira, dos bois e das ovelhas</strong>, D 13.3; compare 5s.; veja Êx 22.28. <span class=\"greek\">ἀ. τῆς ἅλω</span>, 1Cl 29.3. Atribuídas a um profeta, assim como aos sacerdotes e videntes entre os gentios, Artemidoro 3.3, e, no AT, ao sacerdote, D 13.3, 6s.</p>\n<p class=\"entry-text\"><strong>b.</strong> Figuradamente, com os componentes do sentido anterior ainda fortemente presentes.</p>\n<p class=\"entry-text\"><strong>α.</strong> De pessoas, <strong>primícias dos cristãos</strong>. <span class=\"greek\">ἀ. τῆς Ἀσίας</span>, isto é, <strong>o primeiro convertido na Ásia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.5</a>. <span class=\"greek\">ἀ. τῆς Ἀχαΐας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.15</a>. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.13</a>, v.l. <span class=\"greek\">ἀπ’ ἀρχῆς</span>, <strong>os primeiros convertidos de Tessalônica</strong>, assim Harnack, <em>SBBerlAk</em> 1910, 575ss.; plural, 1Cl 42.4.</p>\n<p class=\"entry-text\">Em geral: <span class=\"greek\">ἀ. τις τῶν αὐτοῦ κτισμάτων</span>, <strong>uma espécie de primícias de suas criaturas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.18</a>; compare Fílon, <em>Spec. Leg.</em> 4.180, acerca dos judeus: <span class=\"greek\">τοῦ σύμπαντος ἀνθρώπων γένους ἀπενεμήθη οἷά τις ἀπαρχὴ τῷ ποιητῇ καὶ πατρί</span>; Alexandre de Afrodísias, <em>Fat.</em> 1, II 2 p. 164, 10, <span class=\"greek\">τινὰ ἀπαρχὴν τῶν ἡμετέρων καρπῶν</span>, <strong>uma espécie de primícia de nossa colheita espiritual</strong>; LElliott-Binns, <em>NTS</em> 3, ’56/57, 148–61.</p>\n<p class=\"entry-text\">Aqui, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.4</a>, a ênfase recai menos na sequência cronológica que na qualidade; escólio a Eurípides, <em>Or.</em> 96: <span class=\"greek\">ἀπαρχὴ ἐλέγετο οὐ μόνον τ. πρῶτον τῇ τάξει, ἀλλὰ καὶ τ. πρῶτον τ. τιμῇ</span>. O sentido original fica bastante enfraquecido, de modo que <span class=\"greek\">ἀπαρχή</span> se torna quase equivalente a <span class=\"greek\">πρῶτος</span>. De Cristo: <span class=\"greek\">ἀ. τῶν κεκοιμημένων</span>, <strong>o primeiro dos que adormeceram</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.20</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; HMontefiore, “When Did Jesus Die?”, <em>ET</em> 62, ’60, 53s.; veja também BSpörlein, <em>Die Leugnung der Auferstehung</em>, ’71, sobre 1Co 15; 1Cl 24.1.</p>\n<p class=\"entry-text\"><strong>β.</strong> De coisas — Dio Crisóstomo 54 [71], 2, <span class=\"greek\">ἀπαρχαὶ τῆς σοφίας</span> —: <span class=\"greek\">τὴν ἀ. τοῦ πνεύματος ἔχοντες</span>, <strong>visto que possuímos as primícias do Espírito</strong>, isto é, tanto do Espírito quanto foi derramado até agora e um antegosto das coisas futuras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.23</a>; compare Thieme 25s.; mas veja 2 abaixo. <span class=\"greek\">διδόναι ἀπαρχὰς γεύσεώς τινος</span>, <strong>dar um antegosto de algo</strong>, B 1.7. — ESanders, <em>Jewish Law fr. Jesus to the Mishnah</em>, ’90, 283–308.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Certificado de nascimento</strong> também se ajusta ao contexto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.23</a>; compare Mitt-Wilck. II/2, 372, 4, 7; PFlor 57, 81; 86; 89; PTebt 316, 10; 49; 82; HJones, <em>JTS</em> 23, 1922, 282s.; RTaubenschlag, <em>Opera Minora</em> 2, ’59, 220–21, <strong>cartão de identificação</strong>; L-S-J-M s.v. 7. — HBeer, <em>Ἀπαρχή</em>, diss., Würzburg 1914; EMoutsonlas, <em>Sacris erudiri</em> XV, 5–14, Steenbrugge, ’64; COke, <em>Int</em> 11, ’57, 455–60. — DELG s.v. <span class=\"greek\">ἄρχω</span> A. O. Wilck I 345s. §140. EDNT. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-hapas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅπας</h1><div class=\"entry-meta\"><span class=\"greek\">ασα, αν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hápas⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma intensiva de <span class=\"greek\">πᾶς</span>, <strong>“todo, o todo”</strong>; no plural, <strong>“todos juntos”</strong>. Desde Homero. Ao lado de <span class=\"greek\">πᾶς</span>, no ático, depois de consoantes; para <span class=\"greek\">πᾶς</span> depois de vogais, veja HDiels, <em>GGA</em> 1894, 298ss.; a distinção, porém, não é mantida no NT: B-D-F §275; Rob. 771; veja também Mayser 161s. Sobre o uso com o artigo, W-S. §20, 11.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Usado com substantivo e artigo, <strong>a totalidade de uma massa ou objeto, todo, inteiro</strong>. <span class=\"greek\">ἅ. τὸν λαόν</span> — compare Josefo, <em>Ant.</em> 7.63; 211; Justino, <em>D.</em> 77.4 e outros —, <strong>todo o povo</strong>, em oposição a um indivíduo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.21</a>; compare GPt 8.28 = ASyn. 351, 7. <span class=\"greek\">ἅ. τὸ πλῆθος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">19.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.1\" target=\"_blank\" rel=\"noopener noreferrer\">23.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.24</a>. <span class=\"greek\">ἅ. τὸν βίον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.4</a> v.l., em lugar de <span class=\"greek\">πάντα</span>. <span class=\"greek\">ἅ. τὰ γενόμενα</span>, <strong>tudo o que havia acontecido</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.11</a>. <span class=\"greek\">τὴν ἐξουσίαν ταύτην ἅπασαν</span>, <strong>todo este domínio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.6</a>. <span class=\"greek\">ὁ λαὸς ἅ.</span> — Josefo, <em>Ant.</em> 6.199; 8.101 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.48</a>. <span class=\"greek\">ἐν ἁπάσῃ τῇ πράξει αὐτοῦ</span>, <strong>em tudo o que fazia</strong>, Hs 7.4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Sem substantivo — Justino, <em>A I</em> 15.9; Atanásio 1.2. Masculino <span class=\"greek\">ἅπαντες</span>, <strong>todos, todo mundo</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">7.16</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">9.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">21.4</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">4.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">5.12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">16.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">27.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.28</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.2</a>.</p>\n<p class=\"entry-text\">Neutro <span class=\"greek\">ἅπαντα</span>, <strong>tudo</strong> — TestAbr A 12 p. 92, 18 [Stone p. 32]; Ar. 15.3; Justino, <em>D.</em> 60.2 e outros —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.39</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">11.41</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">15.13</a> v.l. <span class=\"greek\">ἔχειν ἅ. κοινά</span>, <strong>ter tudo em comum</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">4.32</a>. <span class=\"greek\">χρῄζειν τούτων ἁ.</span>, <strong>necessitar de tudo isso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.32</a>. Compare D 3.2–6. — DELG s.v. <span class=\"greek\">πᾶς</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apaspazomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπασπάζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apaspázomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀπησπασάμην</span>; Tb 10.12 S; Himério, <em>Eclog. in Phot.</em> 11.1 p. 194. <strong>Despedir-se de, dizer adeus a</strong>, com <span class=\"greek\">τινά</span>, alguém; Cáriton 3.5.8. <span class=\"greek\">ἀπησπασάμεθα ἀλλήλους</span>, <strong>despedimo-nos uns dos outros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.6</a>. Absolutamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.1</a> D; veja FBlass, <em>Acta apost.</em> 1895 <em>ad loc.</em> — TW.</p>\n</section></article><article id=\"entry-apatao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπατάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apatáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπατήσω</span>, LXX; 1º aoristo <span class=\"greek\">ἠπάτησα</span>, LXX; TestJud 12.3; Taciano 8.3. Passivo: futuro <span class=\"greek\">ἀπατηθήσομαι</span>; aoristo <span class=\"greek\">ἠπατήθην</span>. Veja <span class=\"greek\">ἀπάτη</span>; desde Homero; não em inscrições; raro em papiros, por exemplo PSI 152, 24 [século II d.C.], em contexto fragmentário, talvez <span class=\"greek\">ἠπάτ[ων]</span>; PLond IV, 1345, 13, grafia <span class=\"greek\">ἠπαίτησας</span> [século VII d.C.]; Epicuro p. 298, 29 Us.; Plutarco; Epicteto 4.5.32; Herodiano 2.1.10; LXX; PsSol 16.8; TestSol; TestJob; Test12Patr; GrBar 4.8; ApcEsdr 2.15 p. 26, 18 Tdf.; ApcSed; ApcMos; Fílon, <em>Aet. M.</em> 117; Josefo; Justino; Taciano; Atanásio.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Enganar, desencaminhar</strong>. Com <span class=\"greek\">τινά τινι</span>, <strong>enganar alguém com algo</strong>, Is 36.14. <span class=\"greek\">μηδεὶς ὑμᾶς ἀπατάτω κενοῖς λόγοις</span>, <strong>ninguém vos engane com palavras vazias</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.6</a>; compare TestNapht 3.1; Josefo, <em>Vi.</em> 302, <span class=\"greek\">λόγοις ἀ. τινὰ</span>. <span class=\"greek\">ἀπατῶν αὐτοὺς τ. ἐπιθυμίαις τ. πονηραῖς</span>, Hs 6.2.1.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. καρδίαν ἑαυτοῦ</span>, <strong>enganar a si mesmo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.26</a>; compare Jó 31.27; Justino, <em>D.</em> 141.2 e outros; Atanásio 36.2; Hs 6.4.1 e 4. Com acusativo de pessoa, Dg 2.1; Hm 11.13. No passivo — Josefo, <em>Ant.</em> 12.20; com o sentido <strong>ser desencaminhado</strong>, <em>C. Ap.</em> 2.245 —: <span class=\"greek\">Ἀδὰμ οὐκ ἠπατήθη</span>, <strong>Adão não foi enganado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2.14</a>; a v.l. tem o verbo simples também com referência a Eva.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀπατηθεὶς τῷ κάλλει τῶν γυναικῶν τούτων</span>, <strong>desencaminhado pela beleza dessas mulheres</strong>, Hs 9.13.9; compare TestJud 12.3, <span class=\"greek\">ἠπάτησέ με τὸ κάλλος αὐτῆς</span>; PsSol 16.8, <span class=\"greek\">μὴ ἀπατησάτω με κάλλος γυναικὸς παρανομούσης</span>. <span class=\"greek\">ἀπατάω</span> pode significar <strong>seduzir sexualmente</strong> já em Eratóstenes p. 22, 10.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Médio: <strong>deleitar-se, viver prazerosamente</strong>; com <span class=\"greek\">τρυφᾶν</span>, compare Sir 14.16 e veja <span class=\"greek\">ἀπάτη</span> 2. Hs 6.4.1; 6.5.3s. — DELG s.v. <span class=\"greek\">ἀπάτη</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apate-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάτη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apátē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπατάω</span>; desde Homero.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Engano, caráter enganoso.</strong> Jdth 9.10, 13; 4Mc 18.8; Josefo, <em>Ant.</em> 2.300; SibOr 5.405, <span class=\"greek\">ἀ. ψυχῶν</span>. <span class=\"greek\">ἡ ἀ. τοῦ πλούτου</span>, <strong>a sedução que procede da riqueza</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.19</a>. <span class=\"greek\">ἀ. τῆς ἁμαρτίας</span>, <strong>o caráter enganoso do pecado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.13</a>. Observe que o sentido 2 também é provável para as passagens sinóticas e para Hb 3.13; compare PRein inv. 2069 V, 73, LRobert, <em>Hellenica</em> XI/XII, ’60, 5ss.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. τοῦ κόσμου</span>, Dg 10.7; compare Herm. Wr. 13.1, <span class=\"greek\">ἡ τοῦ κόσμου ἀπάτη</span>. <span class=\"greek\">[τ]ὰς ἐπὶ τὴν ἀπάτην ἀγούσας</span>, talvez <strong>caminhos que conduzem ao engano</strong>, AcPl Ha 9, 13; o texto é fragmentário, veja a nota do editor e também <span class=\"greek\">ἄγω</span> 3, fim. Com <span class=\"greek\">φιλοσοφία</span> — compare Heraclid. Crit., <em>Descriptio Graeciae</em> 1.1 [p. 72, 15 Pfister] —, <strong>engano vazio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.8</a>. <span class=\"greek\">ἐν πάσῃ ἀ. ἀδικίας</span>, <strong>com toda espécie de engano perverso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.10</a>; de fraude enganosa, como Josefo, <em>Ant.</em> 2.284. <span class=\"greek\">ἐπιθυμία τ. ἀπάτης</span>, <strong>desejo enganoso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.22</a>. Com <span class=\"greek\">φιλαργυρία</span>, 2Cl 6.4; com <span class=\"greek\">εἰκαιότης</span>, Dg 4.6; listado com outros pecados, Hm 8.5. Personificado — Hesíodo, <em>Theog.</em> 224; Luciano, <em>De Merc. Cond.</em> 42 —, Hs 9.15.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Especialmente, <strong>prazer, deleite que envolve alguém em pecado</strong>. Assim desde Políbio 2.56.12; 4.20.5; IPriene 113, 64 [84 a.C.; compare Rouffiac 38s.]; Moeris p. 65, <span class=\"greek\">ἀπάτη· ἡ πλάνη παρ’ Ἀττικοῖς … ἡ τέρψις παρ’ Ἕλλησιν</span>; Fílon, <em>Dec.</em> 55. Com <span class=\"greek\">τρυφή</span>, Hs 6.2.1; 6.4.4; 6.5.1 e 3s. No plural — Ps.-Dicearco p. 104s., <span class=\"greek\">ψυχῆς ἀπάται</span> —: Hm 11.12; Hs 6.2.2 e 4; 6.5.6; com <span class=\"greek\">ἐπιθυμίαι</span>, <span class=\"greek\">ἀπάται τοῦ αἰῶνος τούτου</span>, Hs 6.3.3 v.l.</p>\n<p class=\"entry-text\">Daí <span class=\"greek\">ἐντρυφῶντες ἐν ταῖς ἀ.</span>, <strong>entregando-se aos seus prazeres</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.13</a>; v.l. <span class=\"greek\">ἀγάπαις</span>. A mesma variante aparece em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4.19</a> e Ec 9.6 v.l.; veja AvHarnack, <em>Z. Revision d. Prinzipien d. ntl. Textkritik</em> 1916, 109s., e <span class=\"greek\">ἀγάπη</span> 2. — M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-apatelos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπατηλός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apatēlós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπάτη</span>; Homero e outros; também 4Mc 18.8 v.l.; Fílon; Justino, <em>A II</em> 2.11; Atanásio 27.2. <strong>Enganoso, falaz.</strong> <span class=\"greek\">ἀνδρὶ ξένῳ ἀπα[τηλοὺς] καὶ ποικίλους καὶ κενοὺς λόγους διδάσκοντι</span>, <strong>a um estrangeiro que ensina afirmações enganosas, especiosas e sem sentido</strong>, AcPl Ox 6, 11s. = Aa I 241, 14.</p>\n</section></article><article id=\"entry-apatrikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπατρικός</h1><div class=\"entry-meta\"><span class=\"greek\">όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apatrikós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Sem pai.</strong> Fora desta ocorrência, desconhecido; foi restaurado erroneamente em Ox 1081, 34, <span class=\"greek\">α.[… ι]κ̣ου π̄ρ̄σ̄</span>, como <span class=\"greek\">ἀπατρικοῦ πατρός</span>. O editor cita a sugestão do Dr. Bartlet: <span class=\"greek\">ἀγγελικοῦ</span>. <strong>Em vez disso, leia <span class=\"greek\">ἀγεννήτου</span></strong>; veja SJCh 90, 12; veja também <span class=\"greek\">ἀγέννητος</span>. — DELG s.v. <span class=\"greek\">πατήρ</span>.</p>\n</section></article><article id=\"entry-apator-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάτωρ</h1><div class=\"entry-meta\"><span class=\"greek\">ορος</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apátōr⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Sófocles e outros; frequente em papiros. <strong>Sem pai</strong>, de crianças órfãs, abandonadas, afastadas dos pais ou nascidas fora do casamento. Na literatura tratada pelo léxico, somente de Melquisedeque, Gn 14.18ss., com <span class=\"greek\">ἀμήτωρ</span>, <span class=\"greek\">ἀγενεαλόγητος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.3</a>.</p>\n<p class=\"entry-text\">O contexto sugere que ele deve ser entendido como uma espécie de <strong>ser transcendente</strong>; compare Pólux, <em>Onom.</em> 3.25s., <span class=\"greek\">ὁ οὐκ ἔχων μητέρα ἀμήτωρ, καθάπερ ἡ Ἀθηνᾶ, καὶ ὁ οὐκ ἔχων πατέρα ἀπάτωρ ὡς ὁ Ἥφαιστος</span>; <em>Anth. Pal.</em> 15.26; escólio a Teócrito 1.3/4d Wendel [1914], de Pã; PGM 5, 282, do deus Hórus; <span class=\"greek\">Ἀπάτωρα καὶ Δημιουργὸν αὐτὸν … καλοῦσιν</span>, Irineu 1.51 [Harv. I 42, 12]. Veja também <span class=\"greek\">ἀμήτωρ</span>. — DELG s.v. <span class=\"greek\">πατήρ</span>. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-apaugasma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαύγασμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apaúgasma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">αὐγάζω</span>; Heliodoro 5.27.4, <span class=\"greek\">φωτὸς ἀ.</span>; TestAbr A 16 p. 97, 17 [Stone p. 42]; Fílon; Wsd 7.26; Taciano 15.3, <span class=\"greek\">τῆς … ὕλης καὶ πονηρίας</span>, de espíritos hostis; Plutarco tem <span class=\"greek\">ἀπαυγασμός</span>, <em>Mor.</em> 83d e 934d; PGM 4, 1130, <span class=\"greek\">καταύγασμα</span>.</p>\n<p class=\"entry-text\">Ativamente, <strong>resplendor, brilho irradiado</strong>, no sentido de brilho que procede de uma fonte; passivamente, <strong>reflexo</strong>, isto é, brilho refletido. <strong>Nem sempre é possível determinar com certeza qual dos dois sentidos está presente.</strong> O passivo provavelmente deve ser preferido em Plutarco. O ativo parece preferível em Wsd e Fílon — <em>Op. Mundi</em> 146; <em>Spec. Leg.</em> 4.123; <em>Plant.</em> 50 —, correspondendo a Hesíquio: <span class=\"greek\">ἀ. = ἡλίου φέγγος</span>.</p>\n<p class=\"entry-text\">Fílon usa a palavra para a relação do Logos com Deus. Cristo é descrito como <span class=\"greek\">ἀ. τῆς δόξης</span>, <strong>resplendor de sua glória</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.3</a>; o sentido ativo ocorre nos Padres gregos Orígenes, Gregório de Nissa, Teodoreto e Crisóstomo, <span class=\"greek\">φῶς ἐκ φωτός</span>; igualmente Teodoro de Mopsuéstia, Severiano de Gabala e Genádio de Constantinopla: KStaab, <em>Pauluskommentare</em> ’33, 201; 346; 421. Compare <span class=\"greek\">ἀ. τῆς μεγαλωσύνης</span>, 1Cl 36.2. — FDölger, <em>Ac</em> I, 1929, 269ss. DELG s.v. <span class=\"greek\">αὐγή</span>.</p>\n</section></article><article id=\"entry-apaphrizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαφρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apaphrízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἀφρίζω</span>, <strong>“espumar”</strong>; Galeno, CMG V 4, 2 p. 120, 3; 125, 21; Oribásio 5.33.4; <em>Geopon.</em> 8.29; 32. <strong>Lançar fora como espuma</strong>, com <span class=\"greek\">τί</span>, alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 13</a> v.l. — DELG s.v. <span class=\"greek\">ἀφρός</span>.</p>\n</section></article><article id=\"entry-apachthenai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαχθῆναι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apachthē̂nai⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπάγω</span>.</p>\n</section></article><article id=\"entry-apebalon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέβαλον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apébalon⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποβάλλω</span>.</p>\n</section></article><article id=\"entry-apeben-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέβην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apébēn⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποβαίνω</span>.</p>\n</section></article><article id=\"entry-apedeixa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέδειξα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apédeixa⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποδείκνυμι</span>.</p>\n</section></article><article id=\"entry-apedeto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέδετο</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apédeto⟧</span><span class=\"separator\">·</span><span>forma tardia / remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma do grego tardio em lugar de <span class=\"greek\">ἀπέδοτο</span>; veja <span class=\"greek\">ἀποδίδωμι</span>.</p>\n</section></article><article id=\"entry-apedidoun-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπεδίδουν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apedídoun⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποδίδωμι</span>.</p>\n</section></article><article id=\"entry-apethanon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέθανον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apéthanon⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποθνῄσκω</span>.</p>\n</section></article><article id=\"entry-apethemen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπεθέμην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apethémēn⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀποτίθημι</span>.</p>\n</section></article><article id=\"entry-apeidon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπεῖδον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apeîdon⟧</span><span class=\"separator\">·</span><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀφοράω</span>.</p>\n</section></article><article id=\"entry-apeitheia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπείθεια</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apeítheia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀπειθής</span>; Xenofonte, <em>Mem.</em> 3.5.5 e outros; inscrições; papiros; 4Mc 8.9; 18.12.4; PsSol 17.20. <strong>Desobediência.</strong> Na literatura tratada pelo léxico, sempre desobediência para com Deus — compare Josefo, <em>Ant.</em> 3.316 —; às vezes com a conotação de <strong>incredulidade no evangelho cristão</strong>; veja <span class=\"greek\">ἀπειθέω</span>.</p>\n<p class=\"entry-text\">Os que se opõem a Deus são chamados <span class=\"greek\">υἱοὶ τῆς ἀ.</span>, <strong>filhos da desobediência</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">5.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.6</a>; alguns manuscritos omitem a expressão nesta última passagem; veja KKuhn, <em>NTS</em> 7, ’61, 339, para paralelos de Qumran. Da desobediência dos israelitas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">11</a>; de toda a humanidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.32</a>. Personificada, Hs 9.15.3. — DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apeitheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπειθέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apeithéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Em oposição a <span class=\"greek\">πείθομαι</span>; veja <span class=\"greek\">ἀπείθεια</span>. Imperfeito <span class=\"greek\">ἠπείθουν</span>; 1º aoristo <span class=\"greek\">ἠπείθησα</span>. Em lugar de <span class=\"greek\">ἀπιθέω</span>, Homero, desde Ésquilo e Platão. <strong>Desobedecer, ser desobediente.</strong> Compare PYadin 24a, 10, restaurado, de recusa.</p>\n<p class=\"entry-text\">Na literatura tratada pelo léxico, a desobediência é sempre para com Deus, as ordenanças de Deus ou sua revelação; compare Eurípides, <em>Or.</em> 31; Platão, <em>Leg.</em> 741d; Luciano, <em>Dial. Deor.</em> 8.1; SIG 736, 40 [92 a.C.], <span class=\"greek\">τὸν δὲ ἀπειθοῦντα ἢ ἀπρεπῶς ἀναστρεφόμενον εἰς τὸ θεῖον μαστιγούντω οἱ ἱεροί</span>; Dt 1.26; 9.23; Js 5.6; Is 36.5; 63.10; Bar 1.18s.</p>\n<p class=\"entry-text\">Com dativo de pessoa — Nm 14.43, <span class=\"greek\">κυρίῳ</span> —: <span class=\"greek\">τῷ θεῷ</span>, compare Diodoro Sículo 5.74.4, <span class=\"greek\">ἀ. τοῖς θεοῖς</span>; Hierocles 24, 473, <span class=\"greek\">τῷ θεῷ</span>; Josefo, <em>Ant.</em> 9.249; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.30</a>; compare Pol 2.1. <span class=\"greek\">τῷ υἱῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.36</a>.</p>\n<p class=\"entry-text\">Com dativo de coisa — Diodoro Sículo 5.71.5, <span class=\"greek\">τοῖς νόμοις</span> —: <span class=\"greek\">τῇ ἀληθείᾳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.8</a>; Teófilo de Antioquia 1.14 p. 92, 5. <span class=\"greek\">τῷ εὐαγγελίῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.17</a>. <span class=\"greek\">τῷ λόγῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">3.1</a>. <span class=\"greek\">τοῖς εἰρημένοις</span>, 1Cl 59.1. <span class=\"greek\">τοῖς ἐμοῖς ἐλέγχοις</span>, 57.4, Pr 1.25.</p>\n<p class=\"entry-text\">Absolutamente — Dicearco, Fgm. 23 [Ateneu 13 p. 603b], <span class=\"greek\">ἀπειθήσας</span>, <strong>desobediente</strong> —: de membros de uma sinagoga em Corinto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.9</a>; de uma parte de Israel, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.31</a>; de pessoas da Judeia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">15.31</a>. <span class=\"greek\">οἱ ἀπειθήσαντες Ἰουδαῖοι</span>, <strong>os judeus desobedientes</strong>, mas veja abaixo, final, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 14.2</a>. <span class=\"greek\">λαὸς ἀπειθῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.21</a>; B 12.4, ambos Is 65.2. <span class=\"greek\">οἱ ἀπειθοῦντες</span>, IMg 8.2; 1Cl 58.1. Dos gentios, <span class=\"greek\">οἱ ἀπειθήσαντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.31</a>. Em geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.20</a>.</p>\n<p class=\"entry-text\">Em diversas passagens, NRSV e REB, entre outras versões, traduzem <span class=\"greek\">ἀπειθέω</span> por <strong>“não crer”</strong> ou equivalente, <strong>com menor probabilidade</strong>. — DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. TW.</p>\n</section></article>"};
